func reportedConditions(d routingDecision, kind, providerHint string, referenceCount int) []map[string]interface{} {
	var conditions []map[string]interface{}
	if d.UnmigratedKind {
		conditions = append(conditions, map[string]interface{}{
			"code": "UNROUTED_IMAGE_KIND", "severity": "warning",
			"message": "image kind \""+kind+"\" is not in kindProviderRouting and fell back to Stability, which cannot render legible text and ignores reference images; add it to the routing table if that is not what you want",
			"context": map[string]interface{}{"kind": kind, "provider": d.Provider, "routed_kinds": knownRoutedKinds()},
		})
	}
	if d.BadHint {
		conditions = append(conditions, map[string]interface{}{
			"code": "UNRECOGNISED_PROVIDER_HINT", "severity": "warning",
			"message": "provider_hint \""+providerHint+"\" is not a recognised provider; the request fell back to kind routing — fix the imagery_style_guide's provider field (accepted: \"banana\", \"stability\")",
			"context": map[string]interface{}{"kind": kind, "provider_hint": providerHint, "provider": d.Provider},
		})
	}
	if referenceCount > 0 && d.Provider != providerBanana {
		conditions = append(conditions, map[string]interface{}{
			"code": "REFERENCE_ANCHORS_DROPPED", "severity": "warning",
			"message": "request carried reference images but resolved to a provider that ignores them — per-site brand anchoring was silently lost for this asset",
			"context": map[string]interface{}{"kind": kind, "provider": d.Provider, "reference_count": referenceCount},
		})
	}
	return conditions
}

