var conditionReportingAgentTypes = map[string]bool{"image-generator": true}  // guardian veto, round 5 — the gate IS the review record
func senderMayReportConditions(agentType string) bool { return conditionReportingAgentTypes[agentType] }

func parseReportedConditions(normalisedData map[string]interface{}) (conditions []reportedCondition, malformed bool, skipped int) {
	raw, present := normalisedData["reported_conditions"]
	if !present { return nil, false, 0 }              // healthy: one map lookup, silent
	list, ok := raw.([]interface{})
	if !ok { return nil, true, 0 }                     // present but not a list — contract broke
	for _, item := range list {
		if len(conditions) >= maxReportedConditionsPerResponse { break }
		m, ok := item.(map[string]interface{})
		if !ok { skipped++; continue }                   // ROUND 8: counted, not silently dropped
		/* code/severity/message/context; severity defaults 'warning'; message falls back to code */
		if c.Code == "" && c.Message == "" { skipped++; continue }
		conditions = append(conditions, c)
	}
	if len(list) > 0 && len(conditions) == 0 { return nil, true, skipped }  // nothing survived = broken
	return conditions, false, skipped
}

func (s *SagaCoordinator) persistReportedConditions(ctx, state, stepName, response, normalisedData) {
	if _, present := normalisedData["reported_conditions"]; !present { return }
	if !senderMayReportConditions(response.Headers.Sender.AgentType) { s.logger.Warn("reported_conditions from an UNSANCTIONED sender — not persisted; add the agent type to conditionReportingAgentTypes (with review) if this reporter is intended", ...); return }
	conditions, malformed, skipped := parseReportedConditions(normalisedData)
	if malformed { s.logger.Warn("reported_conditions present but MALFORMED — the reporting contract broke; conditions were lost, fix the emitter", ...); return }
	if skipped > 0 { s.logger.Warn("reported_conditions partly UNPARSEABLE — some entries were dropped and are lost; the surviving ones are not the whole picture, fix the emitter", zap.Int("dropped", skipped), zap.Int("parsed", len(conditions)), ...) }
	for _, c := range conditions { entry := s.buildErrorEntry(state, stepName, c.Message); /* sender identity, code, severity, namespaced context */ s.logAgentError(ctx, entry) }
}

