func TestParseReportedConditionsMixedListReportsWhatItDropped(t *testing.T) {
	data := map[string]interface{}{"reported_conditions": []interface{}{
		map[string]interface{}{"code": "UNROUTED_IMAGE_KIND"}, "junk string",
		map[string]interface{}{"code": "UNRECOGNISED_PROVIDER_HINT"}, 42,
		map[string]interface{}{"code": "REFERENCE_ANCHORS_DROPPED"}}}
	got, malformed, skipped := parseReportedConditions(data)
	if malformed { t.Fatal("mixed list must not be flagged wholly malformed") }
	if len(got) != 3 { t.Errorf("parsed %d, want 3 survivors", len(got)) }
	if skipped != 2 { t.Errorf("skipped = %d, want 2 — the caller cannot warn about losses it is not told about", skipped) }
}
